CREATE TABLE IF NOT EXISTS login_codes (id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_sessions (token_hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS product_content (slug TEXT PRIMARY KEY,draft TEXT NOT NULL,published TEXT,revision INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL,published_at INTEGER);
CREATE TABLE IF NOT EXISTS team_members (email TEXT PRIMARY KEY,active INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY,data BLOB NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL);
